import sys

def scan_for_flag(data):
    patterns = [b'flag{', b'FLAG{']
    for pattern in patterns:
        idx = data.find(pattern)
        if idx != -1:
            end = data.find(b'}', idx)
            if end != -1 and end - idx < 128:
                print(data[idx:end+1].decode('utf-8', 'replace'))
                return data[idx:end+1]
    # Try xor single byte keys
    for xor_key in range(1,256):
        xored = bytes([b ^ xor_key for b in data])
        for pattern in patterns:
            idx = xored.find(pattern)
            if idx != -1:
                end = xored.find(b'}', idx)
                if end != -1 and end - idx < 128:
                    print(f'Key {xor_key:#x}:', xored[idx:end+1].decode('utf-8', 'replace'))
                    return xored[idx:end+1]
    print('No flag-like data found.')
    return None

def main():
    with open('/home/ctfplayer/ctf_files/stage-2-nop.bin', 'rb') as f:
        f.seek(0xe0)
        data = f.read()
    flag = scan_for_flag(data)
    if flag:
        sys.exit(0)
    sys.exit(1)

if __name__ == '__main__':
    main()

