import sys
import string

def scan_printable_sequences(data, min_len=8):
    results = []
    current = b''
    start = None
    for i, b in enumerate(data):
        if 32 <= b < 127:
            if start is None:
                start = i
            current += bytes([b])
        else:
            if len(current) >= min_len:
                results.append((start, current))
            current = b''
            start = None
    if len(current) >= min_len:
        results.append((start, current))
    return results

def main():
    path = sys.argv[1] if len(sys.argv)>1 else "stage-2-nop.bin"
    with open(path, "rb") as f:
        bindata = f.read()
    seqs = scan_printable_sequences(bindata[0xe0:])
    for start, seq in seqs:
        print(f"Offset: 0x{start+0xe0:x}: {seq}")

if __name__ == "__main__":
    main()
